func TestNormalizeHTML_HiddenElements(t *testing.T) {
	html := `<html><head><title>테스트</title></head><body>
		<div>본문 텍스트</div>
		<script>var x = 1;</script>
		<style>.a { color: red; }</style>
		<template>템플릿 내용</template>
		<a href="https://example.com">링크 텍스트</a>
		<table><tr><td>셀1</td><td>셀2</td></tr></table>
		<div hidden>숨겨진 div 텍스트</div>
	</body></html>`

	title, text, tables, links, err := normalizeHTML([]byte(html), "https://example.com")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// 제목 확인
	if title != "테스트" {
		t.Errorf("expected title '테스트', got '%s'", title)
	}

	// 텍스트 확인: 링크 텍스트, 표 내용, 숨겨진 요소 내용 제외
	expectedText := "본문 텍스트"
	if text != expectedText {
		t.Errorf("expected text '%s', got '%s'", expectedText, text)
	}

	// 링크 확인
	if len(links) != 1 {
		t.Fatalf("expected 1 link, got %d", len(links))
	}
	if links[0].Text != "링크 텍스트" {
		t.Errorf("expected link text '링크 텍스트', got '%s'", links[0].Text)
	}
	if links[0].URL != "https://example.com" {
		t.Errorf("expected URL 'https://example.com', got '%s'", links[0].URL)
	}

	// 표 확인
	if len(tables) != 1 {
		t.Fatalf("expected 1 table, got %d", len(tables))
	}
	if len(tables[0]) != 1 || len(tables[0][0]) != 2 {
		t.Errorf("unexpected table structure")
	}
	if tables[0][0][0] != "셀1" || tables[0][0][1] != "셀2" {
		t.Errorf("unexpected table content")
	}
}

